package io.rift.cronos;
import org.json.*;import java.math.BigInteger;import java.util.*;import java.io.IOException;
/** Explicit small-page known-NFT observation at a hash-pinned block. Never discovery/completeness. */
public final class HoldingsCheck {
 public static final int MAX=12;private HoldingsCheck(){}
 public interface Check {void run()throws Exception;}
 public static JSONArray inputs(JSONArray rows)throws Exception{if(rows.length()<1||rows.length()>MAX)throw new IllegalArgumentException("Select 1–12 NFT hints");JSONArray clean=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.length()!=3||!row.has("contract")||!row.has("standard")||!row.has("tokenId"))throw new IllegalArgumentException("Unsupported holdings fields");String c=ReadPolicy.address(row.getString("contract")),s=ReadPolicy.standard(row.getString("standard")),id=ReadPolicy.token(row.getString("tokenId"));if(!seen.add(s+":"+c+":"+id))throw new IllegalArgumentException("Duplicate NFT hint");clean.put(new JSONObject().put("contract",c).put("standard",s).put("tokenId",id));}return clean;}
 private static String word(String value){return String.format(java.util.Locale.ROOT,"%64s",value).replace(' ','0');}
 public static JSONObject read(TransferDiscovery.Rpc rpc,String owner,JSONArray requested,Check check)throws Exception{
  owner=ReadPolicy.address(owner);JSONArray rows=inputs(requested);check.run();rpc.requireCronos();Object head=rpc.call("eth_blockNumber",new JSONArray());if(!(head instanceof String)||!((String)head).matches("0x(?:0|[1-9a-fA-F][0-9a-fA-F]{0,13})"))throw new IOException("Invalid head");long height=DiscoveryPolicy.block(new BigInteger(((String)head).substring(2),16).toString());String hash=TransferDiscovery.anchor(rpc,height);JSONArray results=new JSONArray();
  for(int i=0;i<rows.length();i++){check.run();JSONObject r=rows.getJSONObject(i);boolean multi=r.getString("standard").equals("ERC-1155");String data=multi?"0x00fdd58e"+word(owner.substring(2))+word(new BigInteger(r.getString("tokenId")).toString(16)):"0x6352211e"+word(new BigInteger(r.getString("tokenId")).toString(16));Object raw=rpc.call("eth_call",new JSONArray().put(new JSONObject().put("to",r.getString("contract")).put("data",data)).put(new JSONObject().put("blockHash",hash).put("requireCanonical",true)));if(!(raw instanceof String)||!((String)raw).matches("0x[0-9a-fA-F]{64}"))throw new IOException("Malformed NFT observation");String value=((String)raw).substring(2).toLowerCase(Locale.ROOT),actual=multi?owner:"0x"+value.substring(24);if(!multi&&!value.substring(0,24).equals("000000000000000000000000"))throw new IOException("Invalid owner ABI");String amount=multi?new BigInteger(value,16).toString():actual.equals(owner)?"1":"0";results.put(new JSONObject(r.toString()).put("observedOwner",actual).put("amount",amount));}
  check.run();if(!hash.equals(TransferDiscovery.anchor(rpc,height)))throw new IOException("Block changed; entire page rejected");check.run();return new JSONObject().put("chainId",25).put("owner",owner).put("block",Long.toString(height)).put("blockHash",hash).put("hashPinned",true).put("cached",false).put("results",results).put("warning","Provider-reported known-NFT amounts at this block only. Not complete wallet discovery, finality, authenticity, standard certification or trading authorization. No partial page, automatic save, removal or latest-block fallback; EIP-1898 provider support required.");
 }
}
